style.css:
@-moz-document domain("google.com") {
/* 1. Установка вашей картинки на фон */
    body {
        background: url('https://i.pinimg.com/1200x/d8/44/f2/d844f27cf7250c48a8cd641d00743aa5.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. Осветление логотипа Google для видимости на темном фоне */
    .lnXdpd, .k1zZ6c {
        filter: invert(1) brightness(1.8) !important;
    }

    /* 3. Поисковая строка в темно-сливовых тонах (под цвет волос Джолин) с размытием */
    .RNNXgb, .SDk3hd {
        background: rgba(30, 20, 35, 0.75) !important;
        border: 1px solid rgba(235, 150, 50, 0.2) !important;
        backdrop-filter: blur(10px) !important;
        box-shadow: 0 4px 25px rgba(0, 0, 0, 0.4) !important;
    }

    /* 4. Светло-бежевый цвет текста при вводе запроса */
    .gLFyf {
        color: #fbeedb !important;
    }

    /* 5. Кнопки под поиском в цвет осенних листьев */
    .FPdoLc input[type="submit"], .gNO89b {
        background-color: rgba(75, 45, 25, 0.8) !important;
        color: #e6c8a0 !important;
        border: 1px solid rgba(235, 150, 50, 0.15) !important;
        border-radius: 4px !important;
    }

    /* Цвет кнопок при наведении курсора */
    .FPdoLc input[type="submit"]:hover, .gNO89b:hover {
        background-color: rgba(100, 60, 30, 0.9) !important;
        color: #ffffff !important;
    }
}
